typedef float time_value_t;

struct quaternion
{
  float x, y, z, w;
};

template <class T>
class linear_key
{
  time_value_t time;
  T value;

public:
  time_value_t get_time() const { return time; }
};

template <class T>
class linear_track
{
public:
  typedef linear_key<T>* iterator;
  int num_keys;
  iterator m_keys;
};

class anim_control_t
{
  time_value_t current_time;
  time_value_t time_delta;
  time_value_t duration;
  float timescale_factor;
  float cntrl_tween_duration;
  float tween_timer;
  unsigned int flags;
  short loop_count;

public:
  time_value_t get_time() const { return current_time; }
  bool is_reverse() const { return flags & 0x0002; }
  bool was_looped() const { return flags & 0x0400; }
};

template <class animatable_t>
class anim
{
protected:
  unsigned short flags;

public:
  virtual void set_flag(int);
  virtual void clear_flag(int);
  virtual void set_flag(int, bool);
  virtual void set_time(time_value_t);
  virtual void frame_advance(const anim_control_t&, animatable_t*);
  virtual void get_value(const anim_control_t&, animatable_t*) const;
  virtual void get_value(time_value_t, animatable_t*) const;
};

template <class animatable_t, class key_t, class track_t>
class key_anim : public anim<animatable_t>
{
  track_t* track;
  typename track_t::iterator current_key;

public:
  void sync_key(time_value_t t)
  {
    current_key = track->m_keys;
    typename track_t::iterator next_key = current_key;
    ++next_key;
    while (next_key != (track->m_keys + track->num_keys) &&
           t >= (*next_key).get_time())
    {
      ++current_key;
      ++next_key;
    }
  }

  virtual void frame_advance(const anim_control_t& ac, animatable_t* dest)
  {
    if (ac.was_looped())
    {
      sync_key(ac.get_time());
    }
    else if (ac.is_reverse())
    {
      while (current_key != track->m_keys &&
             ac.get_time() < (*current_key).get_time())
      {
        --current_key;
      }
    }
    else
    {
      typename track_t::iterator next_key = current_key;
      ++next_key;
      while (next_key != (track->m_keys + track->num_keys) &&
             ac.get_time() >= (*next_key).get_time())
      {
        current_key = next_key;
        ++next_key;
      }
    }
    if (dest != 0)
    {
      this->get_value(ac, dest);
    }
  }
};

template void key_anim<
  quaternion,
  linear_key<quaternion>,
  linear_track<quaternion>
>::frame_advance(const anim_control_t&, quaternion*);
